{
  "findings": [
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "Access logging is not enabled for this S3 bucket. Without logging, it is difficult to track access patterns or detect unauthorized access."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have server-side encryption enabled. This could lead to sensitive data being stored unencrypted."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "Versioning is not enabled for this S3 bucket. Without versioning, it is not possible to recover from accidental deletions or overwrites."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"b\" {\n  bucket = \"my-tf-test-bucket-ggff\"\n  acl    = \"private\"\n\n  logging {\n    target_bucket = \"my-tf-test-bucket-ggff-logs\"\n    target_prefix = \"log/\"\n  }\n\n  versioning {\n    enabled = true\n  }\n\n  server_side_encryption_configuration {\n    rule {\n      apply_server_side_encryption_by_default {\n        sse_algorithm     = \"aws:kms\"\n      }\n    }\n  }\n}\n\nresource \"aws_s3_bucket\" \"b_logs\" {\n  bucket = \"my-tf-test-bucket-ggff-logs\"\n  acl    = \"log-delivery-write\"\n}",
  "fix_summary": "Enabled access logging by adding a logging block and creating a dedicated logging bucket. Enabled versioning for the bucket. Configured server-side encryption using AWS KMS."
}
